/**
 * attempt-record — the record type of schema id `specstride.attempt/1`, feature 101, data-model.md, "Record of a phase attempt".
 *
 * Generated by `scripts/types.mjs` from `schemas/attempt-record.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface AttemptRecord {
  /**
   * Schema id
   *
   * Type in words: Text.
   */
  schema: string;
  /**
   * Identity of the phase attempt
   *
   * Type in words: Text.
   */
  attemptId: string;
  /**
   * The phase the attempt belongs to
   *
   * Type in words: Whole number.
   */
  phase: number;
  /**
   * The ordinal of the phase attempt inside its phase
   *
   * Type in words: Whole number.
   */
  ordinal: number;
  /**
   * The ordinal of the engine start the phase attempt ran under
   *
   * Type in words: Whole number.
   */
  engineStartOrdinal: number;
  /**
   * The kind that the attempt planner gave (feature 100 annex E §E.1; annex X §X.6 row 9)
   *
   * Type in words: Member of a closed set.
   */
  kind: "plain" | "diagnosed" | "accelerated" | "bumped";
  /**
   * `proposer` or `accelerator`, read from the role registry; the registry is open, so this schema closes no list of roles (F100-FR-023)
   *
   * Type in words: Text, from the role registry.
   */
  role: string;
  /**
   * The harness that ran the passes of the phase attempt
   *
   * Type in words: Text.
   */
  harness: string;
  /**
   * The model that ran the passes of the phase attempt
   *
   * Type in words: Text.
   */
  model: string;
  /**
   * The model tier that ran the passes of the phase attempt
   *
   * Type in words: Text.
   */
  modelTier: string;
  /**
   * The decision record of the attempt planner, as it returned it; absent where no planner ran
   *
   * Type in words: Record, or absent.
   */
  planned?: Record<string, unknown>;
  /**
   * The signature of unmet criteria of the feedback that led to this phase attempt; absent for the first phase attempt of a phase
   *
   * Type in words: Text, or absent.
   */
  signature?: string;
  /**
   * How the phase attempt ended. A field of this record only: the verdict stays one of the three members of the closed set of verdicts (annex X §X.6 row 8), and `gate-failed` and `no-verdict` have no verdict
   *
   * Type in words: Member of a closed set.
   */
  outcome: "approved" | "rejected" | "malformed" | "gate-failed" | "config-error" | "no-verdict";
  /**
   * The verdict, where one exists
   *
   * Type in words: Text, or absent.
   */
  verdictId?: string;
  /**
   * Whether the phase attempt was archived, and the label of the archive
   *
   * Type in words: Record.
   */
  archived: {
    /**
     * Whether the phase attempt was archived
     *
     * Type in words: Truth value.
     */
    archived: boolean;
    /**
     * The label of the archive, or null where the phase attempt was not archived
     *
     * Type in words: Text, or null.
     */
    label: string | null;
  };
}
